begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public;
select plan(40);
select has_function('public','artist_reserve_registration',array['uuid','text','bigint','text'],'artist upload reservation exists');
select has_function('public','artist_submit_registration',array['uuid','jsonb','text','text','text'],'authenticated artist submission exists');
select has_function('public','artist_list_registrations',array[]::text[],'private registration status exists');
select ok(not has_function_privilege('anon','public.artist_reserve_registration(uuid,text,bigint,text)','execute'),'anonymous reservation denied');
select ok(not has_function_privilege('anon','public.artist_submit_registration(uuid,jsonb,text,text,text)','execute'),'anonymous submission denied');
select ok(not has_function_privilege('anon','public.artist_list_registrations()','execute'),'anonymous status denied');
insert into auth.users(id,email,email_confirmed_at) values
('00000000-0000-4000-8000-000000008701','artist@example.invalid',now()),
('00000000-0000-4000-8000-000000008702','other@example.invalid',now()),
('00000000-0000-4000-8000-000000008703','unverified@example.invalid',null);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008703","role":"authenticated"}',true);
select throws_ok($$select public.artist_reserve_registration('87000000-0000-4000-8000-000000000001','image/png',100,'cover.png')$$,'42501','artist_verified_account_required','unverified account denied');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008701","role":"authenticated"}',true);
select throws_ok($$select public.artist_reserve_registration('87000000-0000-4000-8000-000000000001','image/svg+xml',100,'cover.svg')$$,'22023','artist_poster_invalid','unsafe media denied');
select lives_ok($$select public.artist_reserve_registration('87000000-0000-4000-8000-000000000001','image/png',100,'cover.png')$$,'ordinary account reserves without gallery membership');
select is(public.artist_reserve_registration('87000000-0000-4000-8000-000000000001','image/png',100,'cover.png')->>'object_path',public.artist_reserve_registration('87000000-0000-4000-8000-000000000001','image/png',100,'cover.png')->>'object_path','reservation retry returns same path');
select throws_ok($$select public.artist_reserve_registration('87000000-0000-4000-8000-000000000001','image/png',200,'cover.png')$$,'22023','artist_request_conflict','changed reservation retry rejected');
select throws_ok($$select public.artist_submit_registration('87000000-0000-4000-8000-000000000001','{}','Artist','artist','artist@example.invalid')$$,'22023','artist_details_invalid','invalid submission denied');
reset role;
insert into storage.objects(bucket_id,name,owner_id,metadata)
select 'exhibition-media',object_path,user_id::text,jsonb_build_object('mimetype','image/png','size',100)
from content.artist_registrations where request_id='87000000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select public.artist_submit_registration('87000000-0000-4000-8000-000000000001','{"name_ko":"전시","artists":"작가","venue_name_ko":"대관 공간","address_ko":"서울 종로구","opening_date":"2026-10-01","closing_date":"2026-10-31","hours":"10:00–18:00","description_ko":"소개"}','Artist','artist','artist@example.invalid')$$,'verified artist submits private cover without a gallery');
select is(public.artist_submit_registration('87000000-0000-4000-8000-000000000001','{"name_ko":"전시","artists":"작가","venue_name_ko":"대관 공간","address_ko":"서울 종로구","opening_date":"2026-10-01","closing_date":"2026-10-31","hours":"10:00–18:00","description_ko":"소개"}','Artist','artist','artist@example.invalid')->>'status','submitted','submission retry succeeds');
select is(public.artist_reserve_registration('87000000-0000-4000-8000-000000000001','image/png',100,'cover.png')->>'finalized','true','committed retry can skip the immutable cover upload');
select is(jsonb_array_length(public.artist_list_registrations()),1,'artist sees own submission');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008702","role":"authenticated"}',true);
select is(jsonb_array_length(public.artist_list_registrations()),0,'other user cannot see artist contact or notes');
select throws_ok($$select public.artist_reserve_registration('87000000-0000-4000-8000-000000000001','image/png',100,'cover.png')$$,'42501','artist_registration_access_denied','another account cannot reuse reservation');
select throws_ok($$select public.artist_submit_registration('87000000-0000-4000-8000-000000000001','{}','Other','artist','other@example.invalid')$$,'42501','artist_registration_access_denied','another account cannot finalize');
reset role;
select is((select count(*)::integer from content.exhibition_submissions where submitter_user_id='00000000-0000-4000-8000-000000008701'),1,'retry does not duplicate editorial review');
select is((select count(*)::integer from content.gallery_memberships where user_id='00000000-0000-4000-8000-000000008701'),0,'submission never creates gallery authority');
select is((select count(*)::integer from content.submission_media m join content.exhibition_submissions s on s.id=m.submission_id where s.submitter_user_id='00000000-0000-4000-8000-000000008701'),1,'cover reaches existing staff media review');
select ok(not has_table_privilege('authenticated','content.artist_registrations','insert'),'clients cannot forge reservations directly');
select ok(not has_table_privilege('authenticated','content.artist_registrations','select'),'clients cannot read reservation table directly');
select ok(exists(select 1 from content.audit_log where action='artist_exhibition.submitted' and actor_user_id='00000000-0000-4000-8000-000000008701'),'submission is audited');
select ok(exists(select 1 from content.outbox_events where event_type='admin_notification.requested' and payload->>'entity_type'='exhibition_submission'),'existing staff intake notification remains active');
-- Upload, abuse, and publication boundaries ---------------------------------
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008701","role":"authenticated"}',true);
select throws_ok($$select public.artist_reserve_registration('87000000-0000-4000-8000-000000000010','image/png',10485761,'huge.png')$$,'22023','artist_poster_invalid','oversized poster denied on server');
select lives_ok($$select public.artist_reserve_registration('87000000-0000-4000-8000-000000000011','image/png',100,'cover.png')$$,'second bounded upload reservation succeeds');
select throws_ok($$select public.artist_submit_registration('87000000-0000-4000-8000-000000000011','{"name_ko":"전시","artists":"작가","venue_name_ko":"공간","address_ko":"서울","opening_date":"2026-10-01","closing_date":"2026-10-31","hours":"Daily","description_ko":"소개"}','Artist','artist','artist@example.invalid')$$,'22023','artist_poster_missing','missing private poster cannot finalize');
select lives_ok($$select public.artist_reserve_registration('87000000-0000-4000-8000-000000000012','image/png',100,'cover.png')$$,'third bounded reservation succeeds');
select throws_ok($$select public.artist_reserve_registration('87000000-0000-4000-8000-000000000013','image/png',100,'cover.png')$$,'P0001','artist_registration_rate_limited','account rate limit cannot be bypassed by a different contact');
select ok(not content_private.artist_can_upload('submissions/foreign/cover.png'),'unreserved path is not writable');
select ok(not content_private.artist_can_upload((select item->>'object_path' from jsonb_array_elements('[]'::jsonb) item limit 1)),'null path is not writable');
reset role;
select ok(not exists(select 1 from content.artist_registrations r where r.finalized_at is not null and content_private.artist_can_upload(r.object_path)),'finalized cover cannot be overwritten');
insert into auth.users(id,email,email_confirmed_at) values ('00000000-0000-4000-8000-000000008704','publisher@example.invalid',now());
insert into content.staff_members(user_id,role,active) values ('00000000-0000-4000-8000-000000008704','publisher',true);
select set_config('test.artist_submission',(select submission_id::text from content.artist_registrations where request_id='87000000-0000-4000-8000-000000000001'),true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008704","role":"authenticated"}',true);
select lives_ok($$select public.admin_accept_exhibition_submission(current_setting('test.artist_submission')::uuid,'87000000-0000-4000-8000-000000000020')$$,'existing staff acceptance creates a canonical draft');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008701","role":"authenticated"}',true);
select is(public.artist_list_registrations()->0->>'status','accepted','artist sees staff approval');
select is(public.artist_list_registrations()->0->>'published','false','approval is not reported as publication');
reset role;
update auth.users set is_anonymous=true where id='00000000-0000-4000-8000-000000008702';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008702","role":"authenticated"}',true);
select throws_ok($$select public.artist_list_registrations()$$,'42501','artist_verified_account_required','anonymous Auth identity cannot access intake');
reset role;
select ok(not exists(select 1 from content.exhibitions e join content.exhibition_submissions s on s.accepted_exhibition_id=e.id where s.submitter_user_id='00000000-0000-4000-8000-000000008701' and e.gallery_id is not null),'acceptance does not claim or attach gallery authority');
update content.artist_registrations set created_at=now()-interval '2 days' where request_id='87000000-0000-4000-8000-000000000011';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008701","role":"authenticated"}',true);
select throws_ok($$select public.artist_reserve_registration('87000000-0000-4000-8000-000000000011','image/png',100,'cover.png')$$,'22023','artist_registration_expired','expired upload is reported before attempting storage writes');
reset role;
select * from finish();
rollback;
